const characters = new Map(OFFICE_CAST.map(person => [person.id, person]));
const topics = new Map(OFFICE_INTERACTION_TOPICS.map(topic => [topic.id, topic]));

export function getOfficeInteraction(characterId, topicId) {
  const character = characters.get(characterId), topic = topics.get(topicId);
  if (!character || !topic || !Object.hasOwn(DIALOGUE, characterId)) return null;
  const [prompt, response] = DIALOGUE[characterId][topicId];
  return { characterId, name: character.name, topic: topicId, label: topic.label, prompt, response, source: 'scripted' };
}
